@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "./design-tokens.css";

/* Each app scans its own files. This adds the library's components. */
@source "..";

.checkbox-mark:where([data-theme="dark"])[data-disabled] {
  --checkbox-off-mark: #181818;
}

@container style(--ck-color-mode: dark) {
  .checkbox-mark:where(:not([data-theme]))[data-disabled] {
    --checkbox-off-mark: light-dark(#ededed, #181818);
  }
}

/*
 * The component resolves the nearest theme scope.
 * Scopes below set color-scheme, so light-dark follows the nearest scope at
 * any depth. The dark variant treats a light scope inside a dark one as light,
 * but does not turn dark again for a dark scope inside that light scope; use
 * tokens or light-dark for theme literals, which resolve at any depth.
 */
@custom-variant dark (&:where(.dark, .dark *):not(:where(.dark .light, .dark .light *)));

:root,
.light,
.dark {
  --gray-pale-fixed: var(--color-dark-ink);
  --color-fixed-black: light-dark(
    var(--color-light-fixed-black),
    var(--color-dark-fixed-black)
  );
  --color-fixed-white: light-dark(
    var(--color-light-fixed-white),
    var(--color-dark-fixed-white)
  );
  --color-shadow: light-dark(
    var(--color-light-shadow),
    var(--color-dark-shadow)
  );
  --ck-fixed-black: var(--color-fixed-black);
  --ck-fixed-white: var(--color-fixed-white);
  --ck-mask: var(--color-fixed-black);
  --ck-shadow-color: var(--color-shadow);
  --color-transparent: light-dark(
    var(--color-light-transparent),
    var(--color-dark-transparent)
  );
  --color-tooltip-surface: light-dark(
    var(--color-light-tooltip-surface),
    var(--color-dark-tooltip-surface)
  );
  --color-tooltip-ink: light-dark(
    var(--color-light-tooltip-ink),
    var(--color-dark-tooltip-ink)
  );
  --color-media-surface: light-dark(
    var(--color-light-media-surface),
    var(--color-dark-media-surface)
  );
  --color-media-ink: light-dark(
    var(--color-light-media-ink),
    var(--color-dark-media-ink)
  );
  --color-neutral-strong-surface: light-dark(
    var(--color-light-neutral-strong-surface),
    var(--color-dark-neutral-strong-surface)
  );
  --color-avatar-on-surface: var(--ck-fixed-white);
  --color-text-on-status: var(--ck-fixed-white);
  --color-status-success: light-dark(
    var(--color-light-status-success),
    var(--color-dark-status-success)
  );
  --color-status-success-fill: light-dark(
    var(--color-light-status-success-fill),
    var(--color-dark-status-success-fill)
  );
  --color-status-success-solid: light-dark(
    var(--color-light-status-success-solid),
    var(--color-dark-status-success-solid)
  );
  --color-status-success-strong: light-dark(
    var(--color-light-status-success-strong),
    var(--color-dark-status-success-strong)
  );
  --color-status-success-surface: light-dark(
    var(--color-light-status-success-surface),
    var(--color-dark-status-success-surface)
  );
  --color-status-danger: light-dark(
    var(--color-light-status-danger),
    var(--color-dark-status-danger)
  );
  --color-status-danger-fill: light-dark(
    var(--color-light-status-danger-fill),
    var(--color-dark-status-danger-fill)
  );
  --color-status-danger-solid: light-dark(
    var(--color-light-status-danger-solid),
    var(--color-dark-status-danger-solid)
  );
  --color-status-danger-strong: light-dark(
    var(--color-light-status-danger-strong),
    var(--color-dark-status-danger-strong)
  );
  --color-status-danger-surface: light-dark(
    var(--color-light-status-danger-surface),
    var(--color-dark-status-danger-surface)
  );
  --color-status-warning: light-dark(
    var(--color-light-status-warning),
    var(--color-dark-status-warning)
  );
  --color-status-warning-fill: light-dark(
    var(--color-light-status-warning-fill),
    var(--color-dark-status-warning-fill)
  );
  --color-status-warning-solid: light-dark(
    var(--color-light-status-warning-solid),
    var(--color-dark-status-warning-solid)
  );
  --color-status-warning-strong: light-dark(
    var(--color-light-status-warning-strong),
    var(--color-dark-status-warning-strong)
  );
  --color-status-warning-surface: light-dark(
    var(--color-light-status-warning-surface),
    var(--color-dark-status-warning-surface)
  );
  --color-status-caution: light-dark(
    var(--color-light-status-caution),
    var(--color-dark-status-caution)
  );
  --color-status-caution-fill: light-dark(
    var(--color-light-status-caution-fill),
    var(--color-dark-status-caution-fill)
  );
  --color-status-caution-solid: light-dark(
    var(--color-light-status-caution-solid),
    var(--color-dark-status-caution-solid)
  );
  --color-status-caution-strong: light-dark(
    var(--color-light-status-caution-strong),
    var(--color-dark-status-caution-strong)
  );
  --color-status-info: light-dark(
    var(--color-light-status-info),
    var(--color-dark-status-info)
  );
  --color-status-info-fill: light-dark(
    var(--color-light-status-info-fill),
    var(--color-dark-status-info-fill)
  );
  --color-status-info-solid: light-dark(
    var(--color-light-status-info-solid),
    var(--color-dark-status-info-solid)
  );
  --color-status-info-strong: light-dark(
    var(--color-light-status-info-strong),
    var(--color-dark-status-info-strong)
  );
  --color-status-info-surface: light-dark(
    var(--color-light-status-info-surface),
    var(--color-dark-status-info-surface)
  );
  --color-status-discovery: light-dark(
    var(--color-light-status-discovery),
    var(--color-dark-status-discovery)
  );
  --color-status-discovery-fill: light-dark(
    var(--color-light-status-discovery-fill),
    var(--color-dark-status-discovery-fill)
  );
  --color-status-discovery-solid: light-dark(
    var(--color-light-status-discovery-solid),
    var(--color-dark-status-discovery-solid)
  );
  --color-status-discovery-strong: light-dark(
    var(--color-light-status-discovery-strong),
    var(--color-dark-status-discovery-strong)
  );
  --color-status-discovery-surface: light-dark(
    var(--color-light-status-discovery-surface),
    var(--color-dark-status-discovery-surface)
  );
  --color-code-surface: light-dark(
    var(--color-light-code-surface),
    var(--color-dark-code-surface)
  );
  --color-syntax-1: light-dark(
    var(--color-light-syntax-1),
    var(--color-dark-syntax-1)
  );
  --color-syntax-2: light-dark(
    var(--color-light-syntax-2),
    var(--color-dark-syntax-2)
  );
  --color-syntax-3: light-dark(
    var(--color-light-syntax-3),
    var(--color-dark-syntax-3)
  );
  --color-syntax-4: light-dark(
    var(--color-light-syntax-4),
    var(--color-dark-syntax-4)
  );
  --color-syntax-5: light-dark(
    var(--color-light-syntax-5),
    var(--color-dark-syntax-5)
  );
  --color-syntax-name: light-dark(
    var(--color-light-syntax-name),
    var(--color-dark-syntax-name)
  );
  --color-syntax-error: light-dark(
    var(--color-light-syntax-error),
    var(--color-dark-syntax-error)
  );
  --color-editor-cursor: var(--color-status-info);
  --color-editor-line-highlight: color-mix(
    in oklab,
    var(--color-status-info-fill) 12%,
    transparent
  );
  --color-fill-info-soft: color-mix(
    in oklab,
    var(--color-status-info-fill) 13%,
    transparent
  );
  --color-fill-info-surface: var(--color-status-info-surface);
  --shadow-card: 0 4px 16px
    color-mix(in srgb, var(--ck-shadow-color) 5%, transparent);
  --shadow-subtle:
    0 0 2px color-mix(in srgb, var(--ck-shadow-color) 5%, transparent),
    0 4px 6px color-mix(in srgb, var(--ck-shadow-color) 2%, transparent);
  --shadow-split: -16px 0 32px
    color-mix(in srgb, var(--ck-shadow-color) 28%, transparent);
  --shadow-command:
    0 4px 4px color-mix(in srgb, var(--ck-shadow-color) 4%, transparent),
    0 0 1px color-mix(in srgb, var(--ck-shadow-color) 62%, transparent),
    0 4px 14px color-mix(in srgb, var(--ck-shadow-color) 24%, transparent);
  --shadow-toast: 0 4px 12px
    color-mix(in srgb, var(--ck-shadow-color) 10%, transparent);
  --shadow-toast-ring: 0 0 0 2px
    color-mix(in srgb, var(--ck-shadow-color) 20%, transparent);
  --shadow-focus-ring: 0 0 0 2px
    color-mix(in srgb, var(--ck-shadow-color) 40%, transparent);
  --shadow-toolbar: 0 8px 16px -4px
    color-mix(in srgb, var(--ck-shadow-color) 12%, transparent);
}

@theme inline {
  --font-sans: var(--ck-interface-font, var(--ck-default-sans));
  /* Code token colours. */
  --color-syntax-attribute: light-dark(
    var(--color-light-syntax-attribute),
    var(--color-dark-syntax-attribute)
  );
  --color-syntax-comment: light-dark(
    var(--color-light-syntax-comment),
    var(--color-dark-syntax-comment)
  );
  --color-syntax-keyword: light-dark(
    var(--color-light-syntax-keyword),
    var(--color-dark-syntax-keyword)
  );
  --color-syntax-literal: light-dark(
    var(--color-light-syntax-literal),
    var(--color-dark-syntax-literal)
  );
  --color-syntax-string: light-dark(
    var(--color-light-syntax-string),
    var(--color-dark-syntax-string)
  );
  --color-syntax-variable: light-dark(
    var(--color-light-syntax-variable),
    var(--color-dark-syntax-variable)
  );
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--ck-flyout-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-foreground: var(--foreground);
  --color-background: var(--background);
  --color-text: var(--ck-palette-ink);
  --color-text-muted: var(--ck-palette-ink-secondary);
  --color-text-subtle: var(--ck-palette-ink-tertiary);
  --color-chart-blue: var(--color-blue);
  --color-text-notice: var(--ck-palette-label-accent);
  --color-text-on-accent: var(--ck-palette-label-on-accent);
  --color-text-strong-solid: var(--theme-background-control-opaque);
  --color-panel: var(--ck-palette-surface-surface);
  --color-panel-secondary: var(--ck-palette-surface-surface-under);
  --color-panel-tertiary: var(--ck-palette-surface-editor-opaque);
  --color-panel-elevated: var(--ck-palette-surface-elevated-primary);
  --color-panel-elevated-secondary: var(--theme-background-control-opaque);
  --color-panel-card: var(--ck-palette-surface-card, var(--color-panel));
  --color-panel-canvas: color-mix(in srgb, var(--color-panel) 98%, #000);
  --color-fill-viewer-control: light-dark(
    var(--color-panel-elevated),
    var(--color-panel-elevated-secondary)
  );
  --color-stroke-strong: var(--ck-palette-border-heavy);
  --color-stroke-subtle: var(--ck-palette-border-light);
  --color-blue: var(--ck-palette-accent-blue);
  --color-purple: var(--ck-palette-accent-purple);
  --color-red: var(--ck-palette-accent-red);
  --color-chart-red: var(--color-status-danger);
  --color-media-background: var(--color-media-surface);
  --color-media-foreground: var(--color-media-ink);
  --color-fill-artifact-preview: color-mix(
    in srgb,
    var(--color-panel) 98%,
    #000000
  );
  --color-fill-primary-solid: var(--ck-palette-ink);
  --color-fill-primary-soft: var(--ck-palette-surface-control);
  --color-fill-primary-transparent-hover: var(
    --ck-palette-surface-button-secondary-hover
  );
  --color-fill-secondary-soft: var(--ck-palette-surface-button-secondary);
  --color-fill-info-solid: var(--ck-palette-accent-blue);
  --color-fill-control-opaque: var(--theme-background-control-opaque);
  --color-fill-panel: var(--theme-background-panel);
  --color-fill-composer-action-bar: var(--theme-background-composer-action-bar);
  --color-token-border: var(--color-border);
  --color-token-border-heavy: var(--ck-palette-border-heavy);
  --color-token-border-light: var(--ck-palette-border-light);
  --color-token-foreground: var(--ck-palette-ink);
  --color-token-description-foreground: var(--ck-palette-ink-tertiary);
  --color-token-main-surface-primary: var(--ck-palette-surface-surface);
  --color-token-side-bar-background: var(--ck-palette-surface-surface-under);
  --color-token-text-link-foreground: var(--ck-palette-label-accent);
}

/* File type colors: .text-file-* set color to --color-file-*. */
@utility text-file-audio {
  color: var(--color-file-audio);
}
@utility text-file-canvas {
  color: var(--color-file-canvas);
}
@utility text-file-document {
  color: var(--color-file-document);
}
@utility text-file-image {
  color: var(--color-file-image);
}
@utility text-file-pdf {
  color: var(--color-file-pdf);
}
@utility text-file-presentation {
  color: var(--color-file-presentation);
}
@utility text-file-spreadsheet {
  color: var(--color-file-spreadsheet);
}
@utility text-file-three-d {
  color: var(--color-file-three-d);
}
@utility text-file-video {
  color: var(--color-file-video);
}

/* .text-size-chat sizes text from the chat font size. */
@utility text-size-chat {
  font-size: var(--ui-message-text-size, 1rem);
}

/* Typography, spacing and motion scales. */
@theme static {
  --text-xs--line-height: calc(1 / 0.75);
  --text-sm--line-height: calc(1.25 / 0.875);
  --text-base--line-height: calc(1.5 / 1);
  --text-lg--line-height: calc(1.75 / 1.125);
  --text-xl--line-height: calc(1.75 / 1.25);
  --text-2xl--line-height: calc(2 / 1.5);
  --text-3xl--line-height: calc(2.25 / 1.875);
  --text-4xl--line-height: calc(2.5 / 2.25);
  --text-2xs: 0.625rem;
  --text-2xs--line-height: 0.875rem;
  --text-3xs: 0.5rem;
  --text-3xs--line-height: 0.75rem;
  --text-title-xs: 1rem;
  --text-title-sm: 18px;
  --text-title-md: 18px;
  --text-title-lg: 24px;
  --text-title-app: 28px;
  --text-control-label: 13px;
  --text-control-label--line-height: 18px;
  --text-control-label--font-weight: 510;
  --text-control-label--letter-spacing: -0.08px;
  --text-card-title: 22px;
  --text-card-title--line-height: 28px;
  --text-card-title--font-weight: 510;
  --text-card-title--letter-spacing: -0.26px;
  --font-weight-light: 300;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --tracking-tight: -0.025em;
  --tracking-normal: 0em;
  --tracking-wide: 0.025em;
  --shadow-xs: 0 1px 2px 0
    color-mix(in srgb, var(--ck-shadow-color) 5%, transparent);
  --shadow-sm: 0px 1px 2px -1px
    color-mix(in srgb, var(--ck-shadow-color) 8%, transparent);
  --shadow-md: 0px 2px 4px -1px
    color-mix(in srgb, var(--ck-shadow-color) 8%, transparent);
  --shadow-lg: 0px 4px 8px -2px
    color-mix(in srgb, var(--ck-shadow-color) 10%, transparent);
  --shadow-xl: 0px 8px 16px -4px
    color-mix(in srgb, var(--ck-shadow-color) 12%, transparent);
  --shadow-2xl: 0px 16px 32px -8px
    color-mix(in srgb, var(--ck-shadow-color) 19%, transparent);
  --shadow-thin-outline: 0px 0px 0px 0.5px
    color-mix(in srgb, var(--ck-shadow-color) 10%, transparent);
  --ease-in: cubic-bezier(0.4, 0, 1, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --ck-curve-enter: cubic-bezier(0.19, 1, 0.22, 1);
  --ck-curve-exit: cubic-bezier(0.8, 0, 0.4, 1);
  --ck-curve-move: cubic-bezier(0.65, 0, 0.35, 1);
  --ease-basic: ease;
  --radius-base-2xl: 1rem;
  --ease-enter: var(--ck-curve-enter);
  --motion-duration-fast: 0.16s;
  --motion-duration-normal: 0.2s;
  --motion-duration-slow: 0.3s;
  --duration-fast: var(--motion-duration-fast);
  --duration-normal: var(--motion-duration-normal);
  --duration-slow: var(--motion-duration-slow);
  --ck-hairline-width: 0.5px;
  --height-bar: 46px;
  --height-bar-sm: 36px;
  --height-bar-pane: 40px;
  --ck-titlebar-height: calc(var(--spacing) * 11);
  --text-reading: 14px;
  --text-hint-description: 13px;
  --text-hint-description--line-height: 18px;
}

/*
 * Font families and text roles. The roles read the host hooks, and the
 * hooks carry the Electron light and dark values.
 */
@theme inline static {
  --font-content: var(--ui-body-font, var(--font-sans));
  --font-mono: var(--ck-type-code-family, var(--ck-default-mono));
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --color-text-error: var(--ck-palette-label-error);
  --color-text-alert: var(--ck-palette-label-warning);
  --color-text-positive: var(--ck-palette-accent-green);
  --color-chart-purple: var(--ck-palette-accent-purple);
  --color-description: var(--ck-palette-ink-tertiary);
}

/* Heading and body scales. */
:where(:root) {
  --ck-default-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --ck-default-mono:
    ui-monospace, "SFMono-Regular", "SF Mono", menlo, consolas,
    "Liberation Mono", monospace;
  --ck-type-heading-5xl-size: 4.5rem;
  --ck-type-heading-5xl-line-height: 4.5rem;
  --ck-type-heading-5xl-weight: var(--font-weight-semibold);
  --ck-type-heading-5xl-tracking: var(--tracking-tight);
  --ck-type-heading-4xl-size: 3.75rem;
  --ck-type-heading-4xl-line-height: 3.75rem;
  --ck-type-heading-4xl-weight: var(--font-weight-semibold);
  --ck-type-heading-4xl-tracking: var(--tracking-tight);
  --ck-type-heading-3xl-size: 3rem;
  --ck-type-heading-3xl-line-height: 3rem;
  --ck-type-heading-3xl-weight: var(--font-weight-semibold);
  --ck-type-heading-3xl-tracking: var(--tracking-tight);
  --ck-type-heading-2xl-size: 2.25rem;
  --ck-type-heading-2xl-line-height: 2.625rem;
  --ck-type-heading-2xl-weight: var(--font-weight-semibold);
  --ck-type-heading-2xl-tracking: var(--tracking-tight);
  --ck-type-heading-xl-size: 2rem;
  --ck-type-heading-xl-line-height: 2.375rem;
  --ck-type-heading-xl-weight: var(--font-weight-semibold);
  --ck-type-heading-xl-tracking: var(--tracking-tight);
  --ck-type-heading-lg-size: 1.5rem;
  --ck-type-heading-lg-line-height: 1.75rem;
  --ck-type-heading-lg-weight: var(--font-weight-semibold);
  --ck-type-heading-lg-tracking: var(--tracking-normal);
  --ck-type-heading-md-size: 1.25rem;
  --ck-type-heading-md-line-height: 1.625rem;
  --ck-type-heading-md-weight: var(--font-weight-semibold);
  --ck-type-heading-md-tracking: var(--tracking-normal);
  --ck-type-heading-sm-size: 1.125rem;
  --ck-type-heading-sm-line-height: 1.625rem;
  --ck-type-heading-sm-weight: var(--font-weight-semibold);
  --ck-type-heading-sm-tracking: var(--tracking-normal);
  --ck-type-heading-xs-size: 1rem;
  --ck-type-heading-xs-line-height: 1.5rem;
  --ck-type-heading-xs-weight: var(--font-weight-semibold);
  --ck-type-heading-xs-tracking: var(--tracking-normal);
  --ck-type-body-lg-size: 1.125rem;
  --ck-type-body-lg-line-height: 1.8125rem;
  --ck-type-body-lg-weight: var(--font-weight-normal);
  --ck-type-body-lg-tracking: var(--tracking-normal);
  --ck-type-body-md-size: 1rem;
  --ck-type-body-md-line-height: 1.5rem;
  --ck-type-body-md-weight: var(--font-weight-normal);
  --ck-type-body-md-tracking: var(--tracking-normal);
  --ck-type-body-sm-size: 0.875rem;
  --ck-type-body-sm-line-height: 1.25rem;
  --ck-type-body-sm-weight: var(--font-weight-normal);
  --ck-type-body-sm-tracking: var(--tracking-normal);
  --ck-type-body-xs-size: 0.75rem;
  --ck-type-body-xs-line-height: 1.125rem;
  --ck-type-body-xs-weight: var(--font-weight-normal);
