.chat-content {
  width: min(100%, var(--chat-content-width, 46rem));
  margin-inline: auto;
}

.preview-heading {
  font-family: var(--heading-family);
  font-size: var(--text-heading);
  font-weight: var(--font-weight-heading);
  line-height: var(--leading-heading);
}

.key-filter:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.tooltip-popup {
  max-width: min(320px, calc(100vw - 2rem));
  padding: 5px 12px;
  border-radius: 20px;
  background: var(--color-tooltip-surface);
  color: var(--color-tooltip-ink);
  font-size: 13px;
  line-height: 18px;
  transition:
    opacity 150ms,
    transform 150ms;
}
.tooltip-popup[data-starting-style],
.tooltip-popup[data-ending-style] {
  opacity: 0;
  transform: scale(0.96);
}
.segmented-control {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 2px;
  max-width: 100%;
  padding: 2px;
  border-radius: var(--radius-control);
  background: var(--secondary);
}
.segmented-item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 32px;
  padding: 0 12px;
  border-radius: var(--radius-control);
  cursor: pointer;
}
.segmented-item[data-checked] {
  background: var(--primary);
  color: var(--primary-foreground);
}
.segmented-item[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}
.preferences-shell {
  min-height: 100dvh;
}
.preferences-layout {
  display: grid;
  grid-template-columns: var(--chat-sidebar-width, 340px) minmax(0, 1fr);
  min-height: 100dvh;
}
.preferences-nav {
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 24px;
}
.preferences-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.preferences-back {
  margin-top: auto;
  text-decoration: underline;
}
.preferences-content {
  min-width: 0;
  padding: 48px clamp(20px, 6vw, 80px);
  background: var(--card);
}
.preferences-content h2,
.gallery h1 {
  font-family: var(--heading-family);
  font-size: 22px;
  font-weight: 600;
  line-height: 1.3;
}
.preferences-content p {
  margin: 8px 0 20px;
  color: var(--muted-foreground);
}
.key-title {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.key-filter {
  min-height: 40px;
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-control);
  background: var(--background);
}
.key-list {
  flex: none;
  min-width: 0;
}
.key-group {
  margin: 16px 0;
}
.key-group h3 {
  font-weight: 600;
}
.key-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 0;
}
.key-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  min-width: 0;
}
.key-chips kbd {
  padding: 2px 6px;
  border: 1px solid var(--border);
  border-radius: 5px;
  font-family: var(--font-mono);
}
.gallery {
  width: min(100%, 960px);
  margin: auto;
  padding: 24px;
  overflow-wrap: anywhere;
}
.gallery header,
.gallery section {
  margin-bottom: 36px;
}
.gallery h1 {
  margin: 16px 0;
}
.gallery h2 {
  margin-bottom: 12px;
  font-size: 18px;
  font-weight: 600;
}
.gallery h3 {
  margin-top: 12px;
  font-weight: 600;
}
.gallery-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}
.gallery-vertical {
  display: flex;
  gap: 20px;
  margin-top: 20px;
}
@media (max-width: 659px) {
  .preferences-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .preferences-nav {
    padding: 16px;
  }
  .preferences-tabs[data-orientation="vertical"] {
    flex-direction: row;
  }
  .preferences-back {
    margin-top: 0;
  }
  .preferences-content {
    padding: 24px 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .tooltip-popup {
    transition: none;
  }
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    font-size: var(--text-body);
    font-weight: var(--font-weight-body);
    line-height: var(--leading-body);
  }
  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    font-family: var(--heading-family);
  }
  html {
    @apply font-sans;
  }
}

.preferences-demo-page {
  width: min(100% - 32px, 660px);
  margin: 0 auto;
  padding: 32px 0;
}
.preferences-demo-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}
.preferences-demo-header h1 {
  font-size: 22px;
  font-weight: 600;
}
.preferences-demo-header p,
.preferences-demo-status {
  color: var(--muted-foreground);
}
.preferences-demo-stage {
  position: relative;
  overflow: hidden;
  height: 390px;
  border: 1px solid var(--border);
  background: var(--card);
}
.preferences-demo-stage .preferences-shell,
.preferences-demo-stage .preferences-layout {
  min-height: 390px;
}
.preferences-demo-stage .preferences-layout {
  display: block;
}
.preferences-demo-stage .preferences-nav {
  display: none;
}
.preferences-demo-stage .preferences-content {
  padding: 24px;
}
.preferences-demo-cursor {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 110;
  pointer-events: none;
  transition: transform 900ms cubic-bezier(0.22, 1, 0.36, 1);
}
.preferences-demo-cursor svg {
  transform-origin: 2px 2px;
  transition: transform 120ms ease-out;
}
.preferences-demo-cursor[data-pressed="true"] svg {
  transform: scale(0.8);
}
.preferences-demo-cursor[hidden] {
  display: none;
}
.preferences-demo-status {
  margin-top: 12px;
}
@media (max-width: 659px) {
  .preferences-demo-stage .preferences-content {
    padding: 20px 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .preferences-demo-cursor,
  .preferences-demo-cursor svg {
    transition: none;
  }
}

/*
 * Electron corner treatment: where the engine
 * supports corner-shape, radii xs through 4xl scale by 1.25 and rounded
 * utilities md through 4xl use a superellipse. Elsewhere base radii apply.
 */
@supports (corner-shape: superellipse(1.5)) {
  :root {
    --ck-rounding-scale: 1.25;
    --radius-xs: calc(0.25rem * var(--ck-rounding-scale));
    --radius-sm: calc(0.375rem * var(--ck-rounding-scale));
    --radius-md: calc(0.5rem * var(--ck-rounding-scale));
    --radius-lg: calc(0.625rem * var(--ck-rounding-scale));
    --radius-xl: calc(0.75rem * var(--ck-rounding-scale));
    --radius-2xl: calc(1rem * var(--ck-rounding-scale));
    --radius-3xl: calc(1.25rem * var(--ck-rounding-scale));
    --radius-4xl: calc(1.5rem * var(--ck-rounding-scale));
  }

  .rounded-md,
  .rounded-lg,
  .rounded-xl,
  .rounded-2xl,
  .rounded-3xl,
  .rounded-4xl {
    corner-shape: superellipse(1.5);
  }
}

/*
 * Icon sizes. The component defines .icon-xs twice, first from
 * --ck-control-icon-size-xs and later from --icon-size. The later rule wins, so
 * this is the later one.
 */
@utility icon-3xs {
  width: 10px;
  height: 10px;
}

@utility icon-xxs {
  width: 12px;
  height: 12px;
}

@utility icon-2xs {
  width: var(--icon-detail-size, 14px);
  height: var(--icon-detail-size, 14px);
}

@utility icon-xs {
  width: var(--icon-size, 16px);
  height: var(--icon-size, 16px);
}

@utility icon-sm {
  width: 18px;
  height: 18px;
}

@utility icon-base {
  width: 20px;
  height: 20px;
}

@utility icon-md {
  width: 24px;
  height: 24px;
}

@utility icon-lg {
  width: 28px;
  height: 28px;
}

@utility icon-leading {
  width: var(--icon-start-size, 16px);
  height: var(--icon-start-size, 16px);
}

@utility icon-disclosure {
  width: var(--icon-chevron-size, 14px);
  height: var(--icon-chevron-size, 14px);
}

/* KaTeX hard-codes its error color inline, which fails contrast in dark
   themes, so the token wins with importance. */
.katex-error {
  color: var(--color-syntax-error) !important;
}
